SELECT * FROM test_account


        AND uuid = #{uuid}


        AND status = #{status}


        AND is_open = #{isOpen}


        AND group_id = #{groupId}


        AND (nickname LIKE CONCAT('%', #{keyword}, '%') 
             OR account LIKE CONCAT('%', #{keyword}, '%')
             OR remark LIKE CONCAT('%', #{keyword}, '%'))

    AND is_del = 0

ORDER BY gmt_create DESC

SELECT a.*, g.name as groupName FROM test_account a
LEFT JOIN test_account_group g ON a.group_id = g.id

    a.is_del = 0


            AND (a.nickname LIKE CONCAT('%', #{keyword}, '%') 
                 OR a.account LIKE CONCAT('%', #{keyword}, '%')
                 OR a.remark LIKE CONCAT('%', #{keyword}, '%'))




            AND a.group_id IN

                #{groupId}



            AND a.status IN

                #{status}



            AND a.is_open = #{isOpen}


            AND a.gmt_create >= #{startDate}


            AND a.gmt_create < = #{endDate}



        AND a.uuid = #{uuid}




        ORDER BY a.nickname ASC


        ORDER BY a.status DESC, a.gmt_create DESC


        ORDER BY g.sort_num ASC, a.sort_num ASC


        ORDER BY a.gmt_create DESC



    LIMIT #{limit}
